*{box-sizing:border-box} :root{color-scheme:dark;--bg:#080a13;--panel:#101320;--muted:#85899f;--white:#f5f4ff;--cyan:#5be6df;--pink:#ff5cad;--yellow:#ffd36b;--purple:#a68aff;font-family:'Space Grotesk',sans-serif}html,body{margin:0;min-height:100%;background:var(--bg);color:var(--white)}body{min-height:100svh;overflow-x:hidden;background:radial-gradient(ellipse at 75% 40%,#131323 0,transparent 48%),#080a13}.app{width:min(1220px,100%);margin:0 auto;padding:0 56px;position:relative;min-height:100svh}.topbar{height:82px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #ffffff0c}.brand{display:flex;align-items:center;gap:12px;color:var(--white);text-decoration:none;font-size:13px;font-weight:700;letter-spacing:2px}.brand-mark{height:33px;width:33px;display:grid;place-items:center;border:1px solid #5be6df99;border-radius:10px;color:var(--cyan);font-size:18px;transform:rotate(-8deg);box-shadow:0 0 20px #5be6df12}.brand-mark span{color:var(--pink)}.brand-light{font-weight:400;color:#85899f;margin-left:4px}.top-actions{display:flex;align-items:center;gap:10px;font:10px 'DM Mono',monospace;letter-spacing:1.4px;color:#a6a8bb}.live-dot{height:7px;width:7px;border-radius:50%;background:#79edbd;box-shadow:0 0 9px #79edbd}.icon-button{margin-left:14px;background:#ffffff08;border:1px solid #ffffff16;color:#c7c7d7;height:34px;width:36px;border-radius:9px;font-size:16px;cursor:pointer}.icon-button.muted{opacity:.5}.screen{min-height:calc(100svh - 83px);position:relative}.home-screen{display:grid;grid-template-columns:1fr 1.02fr;align-items:center;padding:35px 0 75px}.hero-copy{position:relative;z-index:2;max-width:470px;padding-bottom:16px}.eyebrow{display:flex;align-items:center;gap:10px;font:10px 'DM Mono',monospace;letter-spacing:2px;color:var(--cyan);margin:0 0 18px}.eyebrow-line{width:24px;height:1px;background:var(--cyan)}h1{font-size:clamp(54px,6.6vw,82px);line-height:.98;letter-spacing:-5px;margin:0;font-weight:600}.gradient-text{background:linear-gradient(100deg,#67e5df 5%,#8cbdff 54%,#ed78c6 100%);-webkit-background-clip:text;background-clip:text;color:transparent}.intro{font-size:14px;line-height:1.6;color:#9b9db0;margin:20px 0 26px}.track-card{height:78px;border:1px solid #ffffff14;background:linear-gradient(110deg,#161725c9,#11131fc9);border-radius:11px;display:flex;align-items:center;padding:9px 13px;gap:13px;max-width:420px;box-shadow:0 8px 26px #0002}.cover-art{width:58px;height:58px;border-radius:8px;background:linear-gradient(140deg,#1d6974,#6c2679 68%,#f776ae);position:relative;display:grid;place-items:center;overflow:hidden}.cover-ring{position:absolute;border:1px solid #ffffff55;border-radius:50%;width:48px;height:48px}.ring-two{width:32px;height:32px;border-color:#a6fff988}.cover-core{font-size:23px;color:#cffffb;text-shadow:0 0 12px white}.cover-label{position:absolute;bottom:3px;right:4px;font:6px 'DM Mono',monospace;color:#ffffffb8}.track-info{display:flex;flex-direction:column;gap:3px;flex:1}.track-info strong{font-size:13px;font-weight:600}.track-info>span:last-child{font-size:10px;color:#9699ad}.track-info i,.result-subtitle span{font-style:normal;color:var(--cyan);padding:0 4px}.track-kicker{font:8px 'DM Mono',monospace;letter-spacing:1.4px;color:#7e8298}.track-length{font:10px 'DM Mono',monospace;color:#898da1}.difficulty-row{display:flex;align-items:center;gap:15px;margin:19px 0}.diff-label{font:9px 'DM Mono',monospace;color:#85899e;letter-spacing:1.1px}.difficulty-options{display:flex;gap:5px}.diff-option{font:9px 'DM Mono',monospace;letter-spacing:.7px;color:#86899e;padding:7px 10px;background:transparent;border:1px solid transparent;border-radius:5px;cursor:pointer}.diff-option.active{color:var(--cyan);border-color:#5be6df4a;background:#5be6df0d}.play-button{height:50px;width:min(100%,420px);border:0;border-radius:8px;background:linear-gradient(100deg,#62ded9,#8ec8ee 58%,#d89fd8);display:flex;align-items:center;justify-content:center;gap:13px;color:#0b111a;font:700 11px 'DM Mono',monospace;letter-spacing:1.2px;cursor:pointer;box-shadow:0 8px 24px #65ded925;transition:transform .18s,filter .18s}.play-button:hover{transform:translateY(-2px);filter:brightness(1.08)}.play-icon{font-size:11px}.play-arrow{position:absolute;margin-left:340px;font-size:16px}.control-hint{font:9px 'DM Mono',monospace;letter-spacing:.6px;color:#777b91;margin:15px 0 0}.control-hint span{color:#53566a;padding:0 5px}kbd{border:1px solid #ffffff26;border-radius:3px;padding:2px 4px;color:#b9b9ca;margin:0 1px}.visual-stage{height:440px;position:relative;display:grid;place-items:center;overflow:visible}.stage-glow{position:absolute;width:420px;height:330px;background:radial-gradient(ellipse,#753e8240 0,#294e6f1c 38%,transparent 68%);filter:blur(15px)}.stage-orbit{position:absolute;width:365px;height:365px;border:1px solid #89e8e516;border-radius:50%;transform:rotateX(63deg) rotate(-23deg)}.orbit-b{width:310px;height:310px;border-color:#ee82c519;transform:rotateX(63deg) rotate(34deg)}.stage-disc{width:262px;height:262px;border-radius:50%;position:relative;display:grid;place-items:center;background:radial-gradient(circle at center,#1d293a 0 3%,#081018 3.5% 15%,#162634 15.5% 16%,#101423 16.5% 38%,#263147 38.5% 39%,#0a0d19 40% 72%,#15182b 73% 100%);border:1px solid #a6d9d927;box-shadow:0 15px 80px #0009,inset 0 0 25px #9deee411;animation:rotate 24s linear infinite}.stage-disc:before{content:'';position:absolute;inset:10px;border:1px solid #d5cced22;border-radius:50%;background:repeating-radial-gradient(circle,transparent 0 12px,#ffffff08 13px 14px)}.disc-inner{height:72px;width:72px;border-radius:50%;display:grid;place-items:center;background:linear-gradient(140deg,#3b9595,#8d4eaa 80%);box-shadow:0 0 30px #66d8db55;z-index:1}.disc-star{font-size:28px;color:#d4ffff}.disc-text{position:absolute;top:50%;left:0;right:0;text-align:center;margin-top:55px;font:7px 'DM Mono',monospace;letter-spacing:2px;color:#b8c2cf}.stage-bars{position:absolute;display:flex;align-items:center;gap:5px;height:165px;transform:rotate(-25deg);opacity:.84}.stage-bars i{display:block;width:4px;border-radius:4px;background:linear-gradient(to top,#51d9d1,#d277c6);box-shadow:0 0 10px #63deda55;animation:wave 800ms ease-in-out infinite alternate}.stage-bars i:nth-child(3n){animation-delay:-.4s}.stage-bars i:nth-child(3n + 1){animation-delay:-.7s}.stage-bars i:nth-child(4n){animation-duration:1100ms}.stage-bars i:nth-child(1){height:18%}.stage-bars i:nth-child(2){height:35%}.stage-bars i:nth-child(3){height:52%}.stage-bars i:nth-child(4){height:30%}.stage-bars i:nth-child(5){height:70%}.stage-bars i:nth-child(6){height:88%}.stage-bars i:nth-child(7){height:64%}.stage-bars i:nth-child(8){height:42%}.stage-bars i:nth-child(9){height:75%}.stage-bars i:nth-child(10){height:100%}.stage-bars i:nth-child(11){height:68%}.stage-bars i:nth-child(12){height:43%}.stage-bars i:nth-child(13){height:82%}.stage-bars i:nth-child(14){height:56%}.stage-bars i:nth-child(15){height:36%}.stage-bars i:nth-child(16){height:65%}.stage-bars i:nth-child(17){height:44%}.stage-bars i:nth-child(18){height:72%}.stage-bars i:nth-child(19){height:35%}.stage-bars i:nth-child(20){height:52%}.stage-bars i:nth-child(21){height:25%}.floating-tag{position:absolute;border:1px solid #ffffff1a;background:#111522de;box-shadow:0 8px 22px #0004;border-radius:7px;padding:9px 12px;font:8px 'DM Mono',monospace;letter-spacing:1px;color:#d8d8e6}.floating-tag span{color:var(--cyan);font-size:12px;margin-right:6px}.tag-left{top:72px;left:8%}.tag-right{bottom:83px;right:0;font-size:7px;color:#aaaec0}.tag-right span{color:var(--pink)}.home-footer{position:absolute;bottom:26px;left:0;right:0;display:flex;align-items:center;gap:13px;font:8px 'DM Mono',monospace;letter-spacing:1.3px;color:#676b80}.footer-separator{color:#76dad5}.best-score{margin-left:auto;color:#777b90}.best-score b{color:#c3c4d2;font-weight:400;margin-left:7px}.hidden{display:none!important}.game-screen{padding:18px 0 26px;display:flex;flex-direction:column;min-height:calc(100svh - 83px)}.game-topline{display:flex;align-items:center;justify-content:space-between;height:48px}.back-button{border:0;background:transparent;color:#9b9eb1;display:flex;align-items:center;gap:8px;font:11px 'DM Mono',monospace;cursor:pointer}.back-button:first-letter{font-size:17px}.game-track{display:flex;align-items:center;gap:9px}.mini-cover{width:31px;height:31px;border-radius:6px;display:grid;place-items:center;background:linear-gradient(135deg,#23777d,#a74587);font-size:18px}.game-track>span:last-child{display:flex;flex-direction:column;gap:3px}.game-track b{font-size:11px}.game-track small{font:7px 'DM Mono',monospace;letter-spacing:.7px;color:#86899d}.game-status{font:9px 'DM Mono',monospace;letter-spacing:1px;color:#a1a5b8;display:flex;align-items:center;gap:8px}.scoreboard{display:grid;grid-template-columns:1fr 1fr 1fr;align-items:center;margin:15px auto 13px;width:min(720px,90%)}.scoreboard>div{display:flex;flex-direction:column;gap:4px}.scoreboard>div:last-child{align-items:flex-end}.scoreboard b{font:22px 'DM Mono',monospace;letter-spacing:1px}.stat-label,.combo-stat span{font:8px 'DM Mono',monospace;letter-spacing:1.2px;color:#81859a}.scoreboard b span{font-size:12px;color:#9296aa}.combo-stat{align-items:center!important}.combo-stat b{font-size:25px;color:var(--yellow)}.progress-track{height:2px;background:#ffffff12;position:relative;margin:0 4px 12px}.progress-fill{height:100%;width:0;background:linear-gradient(90deg,var(--cyan),var(--pink));transition:width .12s}.progress-dot{position:absolute;right:0;top:-2px;height:6px;width:6px;border-radius:50%;background:#9295a6}.playfield-wrap{position:relative;flex:1;min-height:330px;max-height:calc(100svh - 280px);width:min(740px,100%);align-self:center;background:linear-gradient(180deg,#121522,#0c0f19);border:1px solid #ffffff14;border-radius:12px;overflow:hidden;box-shadow:0 20px 50px #0004,inset 0 0 50px #7786bb08}#gameCanvas{width:100%;height:100%;display:block;touch-action:none}.lane-controls{position:absolute;bottom:0;left:0;right:0;height:70px;display:grid;grid-template-columns:repeat(4,1fr);background:linear-gradient(180deg,#090b1500,#090b15b5);border-top:1px solid #ffffff0b;touch-action:manipulation}.lane-key{border:0;border-right:1px solid #ffffff09;background:transparent;color:#b9bfd0;display:flex;align-items:center;justify-content:center;gap:9px;touch-action:manipulation;cursor:pointer;transition:background .08s,transform .08s}.lane-key:active,.lane-key.pressed{background:#ffffff16;transform:scale(.97)}.lane-key:nth-child(1){--lane:var(--cyan)}.lane-key:nth-child(2){--lane:var(--pink)}.lane-key:nth-child(3){--lane:var(--yellow)}.lane-key:nth-child(4){--lane:var(--purple)}.lane-symbol{font-size:17px;color:var(--lane);filter:drop-shadow(0 0 7px var(--lane))}.keycap{font:9px 'DM Mono',monospace;color:#74798e;border:1px solid #ffffff21;border-radius:4px;padding:3px 6px}.judge{position:absolute;left:0;right:0;top:54%;text-align:center;pointer-events:none;font:700 16px 'DM Mono',monospace;letter-spacing:2px;opacity:0;transform:translateY(8px);transition:opacity .1s,transform .1s;text-shadow:0 0 14px currentColor}.judge.show{opacity:1;transform:translateY(0)}.judge.perfect{color:var(--cyan)}.judge.good{color:var(--yellow)}.judge.miss{color:var(--pink)}.countdown{position:absolute;inset:0;display:grid;place-items:center;background:#090b159c;font:700 74px 'DM Mono',monospace;color:var(--cyan);text-shadow:0 0 28px #5be6df80;z-index:2}.game-footer{width:min(740px,100%);margin:12px auto 0;display:flex;justify-content:space-between;color:#74788c;font:8px 'DM Mono',monospace;letter-spacing:1.1px}.timing-legend{display:flex;gap:7px;align-items:center}.perfect-dot,.good-dot{height:6px;width:6px;border-radius:50%;background:var(--cyan);margin-left:5px}.good-dot{background:var(--yellow)}.results-overlay{position:fixed;inset:0;background:#05060ccf;backdrop-filter:blur(12px);z-index:10;display:grid;place-items:center;padding:20px}.results-card{position:relative;width:min(425px,100%);padding:28px 32px 24px;text-align:center;border:1px solid #ffffff1d;border-radius:16px;background:radial-gradient(ellipse at 50% 0,#2c1f3a,#111320 58%);box-shadow:0 25px 100px #0009;overflow:hidden}.results-card:before{content:'';position:absolute;top:-135px;left:20%;width:60%;height:200px;background:#8b5aaf3d;filter:blur(60px)}.result-spark{font-size:30px;color:var(--cyan);text-shadow:0 0 20px #5be6df;position:relative}.results-card .eyebrow{justify-content:center;margin:10px 0 7px;font-size:9px}.results-card h2{font-size:35px;letter-spacing:-1.5px;margin:0}.result-subtitle{color:#9a9daf;font-size:11px;margin:6px 0 20px}.result-score-label{font:8px 'DM Mono',monospace;letter-spacing:1.8px;color:#83869b}.result-score{font:500 42px 'DM Mono',monospace;letter-spacing:2px;color:#f5f4ff;margin:3px 0 12px}.result-stats{display:grid;grid-template-columns:repeat(3,1fr);padding:12px 0;border-top:1px solid #ffffff11;border-bottom:1px solid #ffffff11}.result-stats div{display:flex;flex-direction:column;gap:5px}.result-stats b{font:16px 'DM Mono',monospace;color:var(--cyan)}.result-stats span{font:7px 'DM Mono',monospace;letter-spacing:.8px;color:#898da0}.result-grade{font:700 29px 'DM Mono',monospace;color:var(--yellow);text-shadow:0 0 22px #ffd36b8c;margin:12px 0 9px}.result-play{width:100%;height:46px}.result-play .play-arrow{margin-left:300px}.home-link{border:0;background:transparent;color:#898da1;font:9px 'DM Mono',monospace;letter-spacing:1px;margin-top:12px;padding:8px;cursor:pointer}.toast{position:fixed;left:50%;bottom:18px;transform:translate(-50%,15px);opacity:0;background:#171b28;border:1px solid #ffffff1d;padding:9px 15px;border-radius:7px;color:#d4d7e5;font:10px 'DM Mono',monospace;transition:all .2s;pointer-events:none;z-index:20}.toast.show{opacity:1;transform:translate(-50%,0)}@keyframes rotate{to{transform:rotate(360deg)}}@keyframes wave{to{transform:scaleY(.42);filter:hue-rotate(30deg)}}
@media(max-width:850px){.app{padding:0 30px}.home-screen{grid-template-columns:1fr 1fr}.visual-stage{transform:scale(.88);margin-left:-25px;margin-right:-30px}.hero-copy{max-width:390px}.play-arrow{margin-left:310px}.tag-left{left:0}.tag-right{right:-2%}}
@media(max-width:650px){body{background:radial-gradient(ellipse at 50% 40%,#171329 0,transparent 55%),#080a13}.app{padding:0 20px}.topbar{height:64px}.edition{font-size:8px}.top-actions{gap:7px}.icon-button{height:32px;width:34px;margin-left:5px}.screen{min-height:calc(100svh - 65px)}.home-screen{display:flex;flex-direction:column;align-items:stretch;justify-content:flex-start;padding:34px 0 90px}.hero-copy{max-width:none;padding-bottom:0}.eyebrow{margin-bottom:13px}h1{font-size:58px;letter-spacing:-3.8px}.intro{font-size:13px;margin:14px 0 19px}.track-card{max-width:none}.difficulty-row{margin:15px 0;justify-content:space-between}.diff-option{padding:7px 8px;font-size:8px}.play-button{width:100%;height:49px}.play-arrow{margin-left:calc(100% - 58px)}.control-hint{text-align:center;font-size:8px}.visual-stage{order:-1;height:140px;margin:0 -4px 4px;transform:none;overflow:hidden;display:none}.stage-disc{width:132px;height:132px}.stage-disc:before{inset:6px}.disc-inner{height:44px;width:44px}.disc-star{font-size:19px}.disc-text{font-size:5px;margin-top:35px}.stage-orbit{width:175px;height:175px}.orbit-b{width:145px;height:145px}.stage-bars{height:110px;gap:3px;transform:rotate(-25deg) scale(.8)}.floating-tag{font-size:7px;padding:7px}.tag-left{top:7px;left:5%}.tag-right{bottom:8px;right:2%}.home-footer{bottom:17px;gap:8px;font-size:6px;letter-spacing:.8px}.best-score{font-size:6px}.game-screen{min-height:calc(100svh - 65px);padding:9px 0 max(13px,env(safe-area-inset-bottom))}.game-topline{height:40px}.back-button{font-size:9px}.game-track b{font-size:10px}.game-track small{font-size:6px}.mini-cover{height:27px;width:27px}.game-status{font-size:8px}.scoreboard{margin:12px auto;width:95%}.scoreboard b{font-size:19px}.combo-stat b{font-size:23px}.playfield-wrap{width:100%;min-height:280px;max-height:none;flex:1}.lane-controls{height:82px}.lane-key{flex-direction:column;gap:4px}.lane-symbol{font-size:20px}.keycap{font-size:8px}.game-footer{font-size:7px}.judge{top:49%}.results-card{padding:24px 23px 18px}.results-card h2{font-size:32px}.result-score{font-size:38px}.result-play .play-arrow{margin-left:calc(100% - 78px)}}
